import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    book = {}  # id -> [side, price, remaining, seq, active]
    seq_counter = 0

    def add_to_book(oid, side, price, qty, seq):
        book[oid] = [side, price, qty, seq, True]
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    def pop_valid_top(heap):
        while heap:
            top = heap[0]
            oid = top[2]
            info = book.get(oid)
            if info is None or not info[4] or info[2] <= 0:
                heapq.heappop(heap)
                continue
            return top
        return None

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = book.get(oid)
            if info is not None and info[4]:
                info[4] = False
            continue

        seq_counter += 1
        seq = seq_counter

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            while remaining > 0:
                top = pop_valid_top(sell_heap)
                if top is None:
                    break
                s_price, s_seq, s_oid = top
                if typ != 'market' and price is not None and s_price > price:
                    break
                info = book[s_oid]
                avail = info[2]
                trade_qty = min(remaining, avail)
                trades.append([oid, s_oid, s_price, trade_qty])
                remaining -= trade_qty
                info[2] -= trade_qty
                if info[2] <= 0:
                    info[4] = False
                    heapq.heappop(sell_heap)
                # if avail > trade_qty, resting order still has qty, keep in heap
                if info[2] > 0:
                    pass
        else:  # sell
            while remaining > 0:
                top = pop_valid_top(buy_heap)
                if top is None:
                    break
                neg_price, b_seq, b_oid = top
                b_price = -neg_price
                if typ != 'market' and price is not None and b_price < price:
                    break
                info = book[b_oid]
                avail = info[2]
                trade_qty = min(remaining, avail)
                trades.append([b_oid, oid, b_price, trade_qty])
                remaining -= trade_qty
                info[2] -= trade_qty
                if info[2] <= 0:
                    info[4] = False
                    heapq.heappop(buy_heap)

        if typ == 'limit' and remaining > 0:
            add_to_book(oid, side, price, remaining, seq)
        else:
            if oid in book:
                pass  # shouldn't happen for new orders
            book[oid] = [side, price if price is not None else 0, 0, seq, False]

    return trades

